-- P15 — Dez indicadores revisados; referencia PDF e todos os outros dados preservados.
-- Query 305 rev4 congelada em 104; duas regras de peso conservadas na origem.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=100 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
valores AS(SELECT r FROM estudo.notebook_runs n CROSS JOIN LATERAL jsonb_array_elements(n.result->'rows')r WHERE n.id=104 AND n.cell_id=305 AND n.cell_version=4 AND n.status='ok' AND n.frozen AND NOT n.truncated AND n.row_count=22 AND (r->>'ano')::integer=2025 AND r->>'regra'<>'peso_positivo'),
notas AS(SELECT x FROM jsonb_array_elements('[{"ano": 2025, "corte": "2025-12-31", "ordem": 1, "regra": "resultado_atual", "valor": 26.196187620475477, "contas": 46690, "unidade": "percentual", "categoria": "Associaram resultados", "numerador": 12231, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 46690, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 1, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "Vínculo atual (id_usuario) com ao menos um resultado de prova encerrada até o corte. Não restringe modalidade, país ou status do resultado: mede uso do perfil, não a população nacional de concluintes. Não recupera a data de associação nem pessoas excluídas da base.", "base_rotulo": "contas"}, {"ano": 2025, "corte": "2025-12-31", "ordem": 2, "regra": "calendario_registrado", "valor": 21.068751338616405, "contas": 46690, "unidade": "percentual", "categoria": "Incluíram provas ao calendário", "numerador": 9837, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 46690, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 1, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "Mesmo critério da agenda pessoal do portal: registro em tb_evento_corridas_checkin, id_fornecedor NULL, data_checkin até o corte. Inclui inscrição/perfil/calendario e planejamento de eventos futuros. Duplicações de eventos não multiplicam usuários; contagem cumulativa, não somente do ano.", "base_rotulo": "contas"}, {"ano": 2025, "corte": "2025-12-31", "ordem": 3, "regra": "equipe_atual", "valor": 13.167701863354038, "contas": 46690, "unidade": "percentual", "categoria": "Com equipe/assessoria", "numerador": 6148, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 46690, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 1, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "Campo assessoria atual preenchido após trim; não confirma vínculo formal ou histórico. Espaços em branco não contam como equipe.", "base_rotulo": "contas"}, {"ano": 2025, "corte": "2025-12-31", "ordem": 4, "regra": "inscricao_confirmada_atual", "valor": 6.51959734418505, "contas": 46690, "unidade": "percentual", "categoria": "Desafios virtuais", "numerador": 3044, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 46690, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 1, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "Ao menos uma inscrição atualmente confirmada (status C) em desafios, data_inscricao até o corte; conta cada usuário uma vez, cumulativamente. Não é participação comprovada em atividades nem retrato da data de confirmação.", "base_rotulo": "contas"}, {"ano": 2025, "corte": "2025-12-31", "ordem": 5, "regra": "strava_atual", "valor": 11.370743199828658, "contas": 46690, "unidade": "percentual", "categoria": "Vincularam ao Strava", "numerador": 5309, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 46690, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 1, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "strava_id positivo atualmente presente na conta; não testa token, uso ou frequência. Vínculo histórico na data de corte não recuperado.", "base_rotulo": "contas"}, {"ano": 2025, "corte": "2025-12-31", "ordem": 6, "regra": "premium_informado", "valor": 43.73987034035656, "contas": 46690, "unidade": "percentual", "categoria": "Strava Premium", "numerador": 2159, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 4936, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 1, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "strava_premium=true entre contas com strava_id positivo e campo premium informado. Premium NULL não é tratado como falso; não é percentual de todas as contas nem indicador do mercado.", "base_rotulo": "perfis Strava com assinatura informada"}, {"ano": 2025, "corte": "2025-12-31", "ordem": 7, "regra": "seguidores_strava", "valor": 134.41609719058465, "contas": 46690, "unidade": "numero", "categoria": "Média seguidores", "numerador": 708104, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 5268, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 0, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "Média aritmética de strava_full_follower_count não negativo, com strava_id positivo. Seguidores no Strava, não seguidores no Road Runners. Zero conhecido entra na média; campo ausente fica fora.", "base_rotulo": "perfis Strava com seguidores informados"}, {"ano": 2025, "corte": "2025-12-31", "ordem": 8, "regra": "peso_20_300", "valor": 74.9902895947426, "contas": 46690, "unidade": "kg", "categoria": "Peso médio", "numerador": 273864.5376, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 3652, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 1, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "Regra provisória: strava_weight entre 20 e 300 kg, com strava_id positivo. Um peso positivo de 740 kg excluído; zeros e ausências fora da média. Não corrige o cadastro nem calibra a média para coincidir com o PDF. As duas alternativas de peso permanecem no congelamento.", "base_rotulo": "perfis Strava com peso de 20 a 300 kg"}, {"ano": 2025, "corte": "2025-12-31", "ordem": 9, "regra": "pares_por_lista_informada", "valor": 2.484624145785877, "contas": 46690, "unidade": "pares", "categoria": "Pares tênis ativos", "numerador": 13089, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 5268, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 1, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "Média de pares com retired=false por conta Strava com lista JSON em formato array. Lista vazia conhecida conta como zero; lista ausente não conta. Pares aposentados e estado desconhecido não entram no numerador.", "base_rotulo": "perfis Strava com lista de tênis informada"}, {"ano": 2025, "corte": "2025-12-31", "ordem": 10, "regra": "km_por_par_ativo", "valor": 438.11998410879363, "contas": 46690, "unidade": "km", "categoria": "Rodagem por par", "numerador": 5734552.472, "coletado_em": "2026-10-01T09:44:58.49353-03:00", "denominador": 13089, "listas_tenis": 5268, "pares_ativos": 13089, "pesos_20_300": 3652, "casas_decimais": 0, "pesos_positivos": 3653, "premium_informado": 4936, "calendario_sem_data": 0, "pares_com_distancia": 13089, "seguidores_informados": 5268, "tenis_ativo_desconhecido": 0, "nota": "Soma de distance/1000 dos pares ativos com distância numérica não negativa, dividida pelo número desses pares. Unidade original em metros. É km por par ativo; não média de médias por usuário nem quilometragem anual.", "base_rotulo": "pares ativos com distância informada"}]'::jsonb)x),
novas AS(SELECT jsonb_build_object('serie','perfil_cards','categoria',x->>'categoria','status','notebook_em_conciliacao','atual',
 jsonb_build_object('valor',r->'valor','unidade',r->>'unidade','casas_decimais',r->'casas_decimais',
 'contagem',CASE WHEN r->>'unidade'='percentual' THEN r->'numerador' ELSE r->'denominador' END,
 'numerador',r->'numerador','denominador',r->'denominador','populacao',r->'contas','base_rotulo',x->>'base_rotulo',
 'fonte','Notebook · execução #104 · célula 305 rev4 · coleta própria 01/10/2026',
 'nota',(x->>'nota')||' Numerador/soma: '||(r->>'numerador')||'; base informada: '||(r->>'denominador')||'; contas na coorte: '||(r->>'contas'))) AS item
 FROM valores JOIN notas ON x->>'regra'=r->>'regra'),
comparacoes AS(SELECT x AS item FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'comparacoes')x WHERE x->>'serie'<>'perfil_cards' UNION ALL SELECT item FROM novas)
SELECT payload||jsonb_build_object('meta',payload->'meta'||jsonb_build_object('contrato_versao',6,'perfil',
 (SELECT jsonb_build_object('corte',min(r->>'corte'),'coletado_em',min(r->>'coletado_em'),'contas',max((r->>'contas')::bigint),'execucao',104,'celula',305,'revisao',4,
 'regra_peso','Peso: regra provisória de 20 a 300 kg; um valor de 740 kg ficou fora, sem alterar o cadastro. Alternativas e exclusões preservadas no notebook.') FROM valores)),
 'series',(SELECT jsonb_agg(CASE WHEN x->>'id'='perfil_cards' THEN '{"id": "perfil_cards", "status": "transcrito_do_pdf_nao_recalculado", "filtros": {}, "unidade": "texto_publicado", "valores": [{"valor": "+26%", "rotulo": "Associaram resultados"}, {"valor": "+22%", "rotulo": "Incluíram provas ao calendário"}, {"valor": "+13%", "rotulo": "Com equipe/assessoria"}, {"valor": "+6%", "rotulo": "Desafios virtuais"}, {"valor": "+12%", "rotulo": "Vincularam ao Strava"}, {"valor": "+43%", "rotulo": "Strava Premium"}, {"valor": "131", "rotulo": "Média seguidores"}, {"valor": "67.8 kg", "rotulo": "Peso médio"}, {"valor": "2.4", "rotulo": "Pares tênis ativos"}, {"valor": "432 km", "rotulo": "Rodagem por par"}], "ressalva": "P15: reconstrução v1, decisão do responsável em 01/10/2026. O sinal + no PDF significa mais de esse percentual. População: todas as contas existentes cadastradas até o corte, sem excluir país, gênero, administradores ou ausência de Strava. Cada conta uma vez. Atributos atuais não reconstruem o perfil histórico; contagens cumulativas não medem crescimento anual. Premium e médias usam amostras informadas, com bases explícitas; NULL não vira zero. Consulta 305 rev4, congelamento 104; teste da mesma consulta com dados sintéticos 306 rev2, congelamento 105. Valores históricos e comparativos anteriores preservados.", "pagina_pdf": 15, "casas_decimais": null}'::jsonb ELSE x END ORDER BY ord) FROM(SELECT x,row_number() OVER() AS ord FROM jsonb_array_elements(payload->'series')x)t),
 'comparacoes',(SELECT jsonb_agg(item ORDER BY item->>'serie',item->>'categoria') FROM comparacoes),
 'conciliacao','{"divergente": 0, "nao_recalculado": 0, "compativel_no_valor": 0, "notebook_em_conciliacao": 0, "compativel_no_arredondamento": 0}'::jsonb||(SELECT jsonb_object_agg(status,n) FROM(SELECT item->>'status' AS status,count(*) AS n FROM comparacoes GROUP BY 1)t)) AS payload
 FROM anterior WHERE (SELECT count(*) FROM novas)=10 AND (SELECT count(DISTINCT item->>'categoria') FROM novas)=10;
